create extension if not exists pgcrypto;
create table if not exists public.products (id text primary key, name text not null, price text default 'Prix à ajouter', category text not null check (category in ('full','samples','mini')), image text default '', created_at timestamptz default now());
create table if not exists public.pages (id int primary key default 1, data jsonb not null default '{}'::jsonb, updated_at timestamptz default now());
create table if not exists public.contact (id int primary key default 1, data jsonb not null default '{}'::jsonb, updated_at timestamptz default now());
alter table public.products enable row level security; alter table public.pages enable row level security; alter table public.contact enable row level security;
drop policy if exists "public read products" on public.products; create policy "public read products" on public.products for select to anon, authenticated using (true);
drop policy if exists "public read pages" on public.pages; create policy "public read pages" on public.pages for select to anon, authenticated using (true);
drop policy if exists "public read contact" on public.contact; create policy "public read contact" on public.contact for select to anon, authenticated using (true);
revoke insert, update, delete on public.products from anon, authenticated; revoke insert, update, delete on public.pages from anon, authenticated; revoke insert, update, delete on public.contact from anon, authenticated;
drop function if exists public.admin_save_product(text,text,text,text,text,text);
create or replace function public.admin_save_product(p_password text,p_id text,p_name text,p_price text,p_category text,p_image text) returns public.products language plpgsql security definer set search_path=public as $$ begin if encode(digest(p_password,'sha256'),'hex') <> '8c37052d474bd02b693faac977beb5f7b283a67398fed713454a211793034c8c' then raise exception 'invalid admin password'; end if; insert into public.products(id,name,price,category,image) values(p_id,p_name,coalesce(nullif(p_price,''),'Prix à ajouter'),p_category,coalesce(p_image,'')) on conflict(id) do update set name=excluded.name,price=excluded.price,category=excluded.category,image=excluded.image; return (select p from public.products p where p.id=p_id); end; $$;
drop function if exists public.admin_delete_product(text,text);
create or replace function public.admin_delete_product(p_password text,p_id text) returns boolean language plpgsql security definer set search_path=public as $$ begin if encode(digest(p_password,'sha256'),'hex') <> '8c37052d474bd02b693faac977beb5f7b283a67398fed713454a211793034c8c' then raise exception 'invalid admin password'; end if; delete from public.products where id=p_id; return true; end; $$;
drop function if exists public.admin_save_pages(text,jsonb);
create or replace function public.admin_save_pages(p_password text,p_data jsonb) returns public.pages language plpgsql security definer set search_path=public as $$ begin if encode(digest(p_password,'sha256'),'hex') <> '8c37052d474bd02b693faac977beb5f7b283a67398fed713454a211793034c8c' then raise exception 'invalid admin password'; end if; insert into public.pages(id,data,updated_at) values(1,p_data,now()) on conflict(id) do update set data=excluded.data,updated_at=now(); return (select p from public.pages p where p.id=1); end; $$;
drop function if exists public.admin_save_contact(text,jsonb);
create or replace function public.admin_save_contact(p_password text,p_data jsonb) returns public.contact language plpgsql security definer set search_path=public as $$ begin if encode(digest(p_password,'sha256'),'hex') <> '8c37052d474bd02b693faac977beb5f7b283a67398fed713454a211793034c8c' then raise exception 'invalid admin password'; end if; insert into public.contact(id,data,updated_at) values(1,p_data,now()) on conflict(id) do update set data=excluded.data,updated_at=now(); return (select c from public.contact c where c.id=1); end; $$;
grant usage on schema public to anon, authenticated; grant select on public.products,public.pages,public.contact to anon, authenticated; grant execute on function public.admin_save_product(text,text,text,text,text,text), public.admin_delete_product(text,text), public.admin_save_pages(text,jsonb), public.admin_save_contact(text,jsonb) to anon, authenticated;
